INSERT INTO found_bug
(id,title,severity,category,ddl_op,feature,symptom,repro,expected,actual,root_cause,fix_hint,oracle,method,root_cause_id,affects,confirmed,status,notes)
VALUES
(1770003,'IMPORT INTO reports success and leaves a missing secondary index when a chunk writer Close fails','high','correctness/data-integrity','IMPORT INTO from file','per-chunk local engine writer finalization','IMPORT INTO reports a finished job and imported rows, but a secondary-index scan misses those rows and ADMIN CHECK TABLE reports 8223.','Create a table with a secondary index and a three-row CSV. Run file IMPORT INTO with THREAD=1 and CHECKSUM_TABLE=off. Inject one index EngineWriter.Close error before its final flush. Compare the import terminal status, table scan, forced-index scan, and ADMIN CHECK TABLE.','A terminal writer Close failure must fail the chunk and dominate task success. No import may be reported finished while required row or index KVs are missing.','The job is finished with client exit 0 and Imported_Rows=3. The table scan returns 3, the forced index scan returns 0, and ADMIN CHECK TABLE reports ERROR 8223.','ProcessChunk defers data and index EngineWriter.Close, logs Close errors, but returns only the earlier ProcessChunkWithWriter result. Close is the final flush and destroys the writer buffer, so the task imports incomplete engines as successful.','Use a named return and combine every deferred writer Close error with the processing error before the task can close/import engines.','import-status-row-index-admin-check-coherence','DEFERRED_TERMINAL_ERROR_DOMINATES_SUCCESS','importinto-processchunk-writer-close-false-success','master 13282a8bd06b; file IMPORT INTO local sort with checksum off or optional',1,'confirmed','Current-source local RED and named-return GREEN. Real PD/TiKV testbed RED: success plus 3/0 and ADMIN 8223; no-fault 3/3; counterfactual error plus 0/0 and ADMIN green. Discovery used current source only; issue/history searches were post-RED. Distinct from id1260008 and id1590002.');
